var DRY_RUN = true;                                                // ✏️ false = apply
var MAP_NAME = 'Import Asana HR Project Portfolio Transform Map';  // ✏️ exact map name
var S = {
 "user": "// Field map script for a USER field on the Asana projects map (u_import_asana_hr_project_portfolio -> pm_project).\n// Asana holds people as NAMES in custom fields, not emails:\n//   \"PM Assigned\"            (u_pm_assigned, filled 51/55)          -> project_manager (and assigned_to)\n//   \"HRSP / SME / Project Lead\" (u_hrsp___sme___project_lead, 6/55) -> u_business_owner\n// Values seen: \"Jen Angle\", \"Jen Angle/Carrie Lynn\" (first person used), \"N/A\", \"TBD\", \"DJE\", \"Protiviti\".\n// Regular Asana projects have no \"PM Assigned\": the owner's email (column Assignee Email) is used instead.\n// Match: exact active name; else last name + first name starting with the Asana first name (\"Jen\" -> \"Jennifer\"),\n// only when exactly ONE active user matches. No match -> blank + a log line (never \"undefined\").\n// In the field map: Use source script = true, Choice action = ignore. \u270f\ufe0f COLUMN per field map.\nanswer = (function transformEntry(source) {\n    var COLUMN = 'u_pm_assigned';               // \u270f\ufe0f 'u_pm_assigned' or 'u_hrsp___sme___project_lead'\n    var FALLBACK_EMAIL = true;                 // \u270f\ufe0f PM field blank -> the Asana owner/assignee email (regular Asana projects:\n                                               //    the project OWNER is the PM and has no \"PM Assigned\" field)\n    var raw = (source.getValue(COLUMN) || '').trim();\n    var name = raw.split(/\\s*[\\/,;&]\\s*|\\s+and\\s+/i)[0].trim();\n    if (!name || /^(n\\/?a|tbd|none|undefined)$/i.test(name)) {\n        var em = (source.getValue('u_assignee_email') || '').toLowerCase().trim();\n        if (!FALLBACK_EMAIL || !em || em == 'undefined') return '';\n        var ue = new GlideRecord('sys_user');\n        ue.addQuery('email', em); ue.orderByDesc('active'); ue.setLimit(1); ue.query();\n        if (ue.next()) return ue.getUniqueValue();\n        log.warn('Asana: no ServiceNow user with email ' + em + ' on ' + source.getValue('u_name'));\n        return '';\n    }\n    // HR PM list (Richard Becker): last name -> emails. Exact and safe even with duplicate user records in DEV.\n    var PM = { angle: ['jennifer.angle@bsmhealth.org', 'jennifer.angle@mercy.com'], lynn: ['carrie_lynn@bsmhealth.org', 'carrie_lynn@mercy.com'],\n        mcclure: ['kamcclure@bsmhealth.org', 'kamcclure@mercy.com'], mcdearmon: ['kmcdearmon@mercy.com'], hayes: ['lhayes@mercy.com'],\n        caldwell: ['mcaldwell4@mercy.com'], whitis: ['iwhitis@bsmhealth.org', 'iwhitis@mercy.com'],\n        warfield: ['awarfield@bsmhealth.org', 'awarfield@mercy.com'], trucksis: ['menims@bsmhealth.org', 'menims@mercy.com'],\n        becker: ['rbecker0@mercy.com', 'rbecker0@bsmhealth.org'] };\n    var last = name.toLowerCase().split(/\\s+/).pop();\n    if (PM[last]) {\n        var up = new GlideRecord('sys_user');\n        up.addQuery('email', 'IN', PM[last].join(',')); up.orderByDesc('active'); up.setLimit(1); up.query();\n        if (up.next()) return up.getUniqueValue();\n    }\n    var u = new GlideRecord('sys_user');\n    u.addQuery('name', name); u.addQuery('active', true); u.query();\n    if (u.getRowCount() == 1 && u.next()) return u.getUniqueValue();\n    var parts = name.split(/\\s+/);\n    if (parts.length >= 2) {\n        u = new GlideRecord('sys_user');\n        u.addQuery('last_name', parts[parts.length - 1]);\n        u.addQuery('first_name', 'STARTSWITH', parts[0]);\n        u.addQuery('active', true);\n        u.query();\n        if (u.getRowCount() == 1 && u.next()) return u.getUniqueValue();\n    }\n    log.warn('Asana ' + COLUMN + ': no single ServiceNow user for \"' + raw + '\" on ' + source.getValue('u_name'));\n    return '';\n})(source);\n",
 "owner": "// Field map script for a USER field on the Asana projects map (u_import_asana_hr_project_portfolio -> pm_project).\n// Asana holds people as NAMES in custom fields, not emails:\n//   \"PM Assigned\"            (u_pm_assigned, filled 51/55)          -> project_manager (and assigned_to)\n//   \"HRSP / SME / Project Lead\" (u_hrsp___sme___project_lead, 6/55) -> u_business_owner\n// Values seen: \"Jen Angle\", \"Jen Angle/Carrie Lynn\" (first person used), \"N/A\", \"TBD\", \"DJE\", \"Protiviti\".\n// Regular Asana projects have no \"PM Assigned\": the owner's email (column Assignee Email) is used instead.\n// Match: exact active name; else last name + first name starting with the Asana first name (\"Jen\" -> \"Jennifer\"),\n// only when exactly ONE active user matches. No match -> blank + a log line (never \"undefined\").\n// In the field map: Use source script = true, Choice action = ignore. \u270f\ufe0f COLUMN per field map.\nanswer = (function transformEntry(source) {\n    var COLUMN = 'u_hrsp___sme___project_lead';               // \u270f\ufe0f 'u_pm_assigned' or 'u_hrsp___sme___project_lead'\n    var FALLBACK_EMAIL = false;                // \u270f\ufe0f PM field blank -> the Asana owner/assignee email (regular Asana projects:\n                                               //    the project OWNER is the PM and has no \"PM Assigned\" field)\n    var raw = (source.getValue(COLUMN) || '').trim();\n    var name = raw.split(/\\s*[\\/,;&]\\s*|\\s+and\\s+/i)[0].trim();\n    if (!name || /^(n\\/?a|tbd|none|undefined)$/i.test(name)) {\n        var em = (source.getValue('u_assignee_email') || '').toLowerCase().trim();\n        if (!FALLBACK_EMAIL || !em || em == 'undefined') return '';\n        var ue = new GlideRecord('sys_user');\n        ue.addQuery('email', em); ue.orderByDesc('active'); ue.setLimit(1); ue.query();\n        if (ue.next()) return ue.getUniqueValue();\n        log.warn('Asana: no ServiceNow user with email ' + em + ' on ' + source.getValue('u_name'));\n        return '';\n    }\n    // HR PM list (Richard Becker): last name -> emails. Exact and safe even with duplicate user records in DEV.\n    var PM = { angle: ['jennifer.angle@bsmhealth.org', 'jennifer.angle@mercy.com'], lynn: ['carrie_lynn@bsmhealth.org', 'carrie_lynn@mercy.com'],\n        mcclure: ['kamcclure@bsmhealth.org', 'kamcclure@mercy.com'], mcdearmon: ['kmcdearmon@mercy.com'], hayes: ['lhayes@mercy.com'],\n        caldwell: ['mcaldwell4@mercy.com'], whitis: ['iwhitis@bsmhealth.org', 'iwhitis@mercy.com'],\n        warfield: ['awarfield@bsmhealth.org', 'awarfield@mercy.com'], trucksis: ['menims@bsmhealth.org', 'menims@mercy.com'],\n        becker: ['rbecker0@mercy.com', 'rbecker0@bsmhealth.org'] };\n    var last = name.toLowerCase().split(/\\s+/).pop();\n    if (PM[last]) {\n        var up = new GlideRecord('sys_user');\n        up.addQuery('email', 'IN', PM[last].join(',')); up.orderByDesc('active'); up.setLimit(1); up.query();\n        if (up.next()) return up.getUniqueValue();\n    }\n    var u = new GlideRecord('sys_user');\n    u.addQuery('name', name); u.addQuery('active', true); u.query();\n    if (u.getRowCount() == 1 && u.next()) return u.getUniqueValue();\n    var parts = name.split(/\\s+/);\n    if (parts.length >= 2) {\n        u = new GlideRecord('sys_user');\n        u.addQuery('last_name', parts[parts.length - 1]);\n        u.addQuery('first_name', 'STARTSWITH', parts[0]);\n        u.addQuery('active', true);\n        u.query();\n        if (u.getRowCount() == 1 && u.next()) return u.getUniqueValue();\n    }\n    log.warn('Asana ' + COLUMN + ': no single ServiceNow user for \"' + raw + '\" on ' + source.getValue('u_name'));\n    return '';\n})(source);\n",
 "portfolio": "// \"Import Asana HR Project Portfolio Transform Map\": field map -> primary_portfolio (\"Portfolio\")\n// Every migrated Asana project goes under the ServiceNow portfolio \"HR\".\n// Field Maps > New: Target field = primary_portfolio, Use source script = true, Choice action = ignore.\n// No active portfolio named NAME -> blank + a log line (create the portfolio first - reference data).\nanswer = (function transformEntry(source) {\n    var NAME = 'HR';                                   // \u270f\ufe0f exact ServiceNow portfolio name\n    var pf = new GlideRecord('pm_portfolio');\n    pf.addQuery('name', NAME);\n    pf.addQuery('active', true);\n    pf.query();\n    if (pf.next()) return pf.getUniqueValue();\n    log.warn('No active ServiceNow portfolio \"' + NAME + '\" - portfolio left blank on ' + source.getValue('u_name'));\n    return '';\n})(source);\n",
 "fa": "// \"Import Asana HR Project Portfolio Transform Map\": field map -> u_functional_area (Functional Area)\n// Use source script = true, Choice action = ignore. Replaces the current u_functional_area script.\n// Source: the tracker SECTION (column Section/Column), e.g. \"Retirement\" -> Retirement, \"Labor\" -> Labor.\n// Matched against the ACTIVE Functional Area choices by label or value (any case, \"&\"/\"and\" and spaces ignored).\n// \"Benefits & Well-Being\" is two choices in ServiceNow, so the row decides:\n//   1. HR COEs Engaged names \"HWB - Well-Being\" and not \"HWB - Benefits\"  -> Well-Being\n//   2. HR COEs Engaged names \"HWB - Benefits\"                              -> Benefits\n//   3. else the project name: well-being / wellness / be well / fit / flu  -> Well-Being\n//   4. else                                                                -> Benefits\n// No matching choice -> blank + a log line (no new choices are made). Regular Asana projects have no section -> blank.\nanswer = (function transformEntry(source) {\n    var ALIASES = {                          // \u270f\ufe0f section (normalised) -> Functional Area choice LABEL, only where they differ\n        // 'hrsps hr ops': 'HR Operations',\n    };\n    function n(x) { return String(x || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim(); }\n    var section = (source.getValue('u_section_column') || '').trim();\n    if (!section || section == 'undefined') return '';\n    var want = section;\n    if (n(section) == n('Benefits & Well-Being')) {\n        var coes = n(source.getValue('u_hr_coes_engaged')), name = n(source.getValue('u_name'));\n        var wb = coes.indexOf('hwb well being') > -1, ben = coes.indexOf('hwb benefits') > -1;\n        if (wb && !ben) want = 'Well-Being';\n        else if (ben) want = 'Benefits';\n        else if (/well being|wellness|be well|fit testing|flu/.test(name)) want = 'Well-Being';\n        else want = 'Benefits';\n    }\n    if (ALIASES[n(want)]) want = ALIASES[n(want)];\n    var c = new GlideRecord('sys_choice');\n    c.addQuery('name', 'IN', 'pm_project,planned_task,task');\n    c.addQuery('element', 'u_functional_area');\n    c.addQuery('inactive', false);\n    c.query();\n    while (c.next()) if (n(c.getValue('label')) == n(want) || n(c.getValue('value')) == n(want)) return c.getValue('value');\n    log.warn('Functional Area: no choice for \"' + want + '\" (section \"' + section + '\") on ' + source.getValue('u_name'));\n    return '';\n})(source);\n",
 "desc": "// Notes + the HR-only attributes as a readable block (agreed: description block, D6).\nanswer = (function transformEntry(source) {\n    function v(c) { var x = (source.getValue(c) || '').trim(); return (x == 'undefined' || x == 'null') ? '' : x; }\n    var lines = [];\n    if (v('u_notes')) lines.push(v('u_notes'), '');\n    [['Size/Complexity', 'u_size_complexity'], ['I&T Integrations Needed', 'u_i_t_integrations_needed'],\n     ['Strategy Focus', 'u_strategy_focus'], ['Strategy Timeline', 'u_strategy_timeline'],\n     ['Entity/Organization', 'u_entity_organization'], ['HR COEs Engaged', 'u_hr_coes_engaged'],\n     ['HR Cross-Impacts', 'u_hr_cross_impacts'], ['Asana Project Status', 'u_project_status']].forEach(function (f) {\n        if (v(f[1])) lines.push(f[0] + ': ' + v(f[1]));\n    });\n    if (!lines.length) return '';\n    return 'Migrated from Asana (HR Project Portfolio 2026)\\n' + lines.join('\\n');\n})(source);\n",
 "start": "answer = (function transformEntry(source) {\n    var d = (source.getValue('u_start_date') || '').substring(0, 10);\n    return /^\\d{4}-\\d{2}-\\d{2}$/.test(d) ? d + ' 08:00:00' : '';\n})(source);\n",
 "end": "answer = (function transformEntry(source) {\n    var d = (source.getValue('u_due_date') || '').substring(0, 10);\n    return /^\\d{4}-\\d{2}-\\d{2}$/.test(d) ? d + ' 17:00:00' : '';\n})(source);\n",
 "state": "// \"Import Asana HR Project Portfolio Transform Map\": field map -> state (Use source script, Choice action = ignore)\n// The project's State comes from the Asana \"Project Status\" field of the tracker row - NOT from its tasks (most rows\n// have no subtasks). Looked up by choice LABEL, so it only writes a state that exists and is active on pm_project.\n// A label that does not exist (DEV has no \"Work in Progress\" on projects - same open item as Adaptive) -> blank + log.\nanswer = (function transformEntry(source) {\n    var LABEL = {                                   // \u270f\ufe0f Asana Project Status (lower case) -> ServiceNow state LABEL\n        'not started': 'Pending',\n        'started/scoping': 'Investigating',\n        'in progress': 'Work in Progress',\n        'delayed': 'Work in Progress',\n        'on hold': 'Work in Progress',              // + the On Hold box: PART B\n        'completed': 'Closed Complete',\n        'cancelled': 'Closed Incomplete'\n    };\n    var s = (source.getValue('u_project_status') || '').toLowerCase().trim();\n    if (!s || s == 'undefined') return '';\n    var label = LABEL[s];\n    if (!label) { log.warn('Asana Project Status \"' + s + '\" not mapped on ' + source.getValue('u_name')); return ''; }\n    var c = new GlideRecord('sys_choice');\n    c.addQuery('name', 'IN', 'pm_project,planned_task,task');\n    c.addQuery('element', 'state');\n    c.addQuery('label', label);\n    c.addQuery('inactive', false);\n    c.orderBy('name');                              // pm_project's own choices first\n    c.query();\n    if (c.next()) return c.getValue('value');\n    log.warn('No active project state \"' + label + '\" (Asana \"' + s + '\") on ' + source.getValue('u_name'));\n    return '';\n})(source);\n\n",
 "onhold": "answer = (function transformEntry(source) {\n    return (source.getValue('u_project_status') || '').toLowerCase().trim() == 'on hold' ? 'true' : 'false';\n})(source);\n",
 "sites": "// \"Import Asana HR Project Portfolio Transform Map\": field map -> u_sites (Sites, a LIST of Question Choices)\n// Use source script = true, Choice action = ignore. Replaces the current u_sites script.\n// Asana \"Organization\" (column Entity/Organization), e.g. \"BSMH, RSFH\" -> the matching Question Choice records.\n// Sites choices seen in DEV: Advantus Health Partners, Affiliate, Chesapeake (GHC), Cincinnati, Conduit Health,\n// Covenant (GHC), Ensemble, Enterprise, Global Business Services (GBS), Greenville, Hampton Roads, Harness Health\n// Partners, Home Office, Ireland, Kentucky, Lima, Lorain, Nationwide (GHC), Richmond, Roper St. Francis Healthcare,\n// Shelter Arms (GHC), Springfield, Toledo, Wyandot (GHC), Youngstown.\n// Unmatched values -> left out + a log line. Nothing matched -> blank (never \"undefined\").\nanswer = (function transformEntry(source) {\n    var ALIASES = {                                   // \u270f\ufe0f Asana value (lower case) -> Sites choice text\n        'rsfh': 'Roper St. Francis Healthcare',\n        'gbs': 'Global Business Services (GBS)'\n        // 'bsmh': '???',                             // \u270f\ufe0f confirm with HR PMO / BA (Enterprise? Home Office?)\n        // 'external partners': '???'\n    };\n    var QUESTION = '';                                // \u270f\ufe0f optional: sys_id of the question these choices belong to\n    var raw = (source.getValue('u_entity_organization') || '').trim();\n    if (!raw || raw == 'undefined') return '';\n    var ids = [];\n    raw.split(/\\s*[,;]\\s*/).forEach(function (v) {\n        if (!v) return;\n        var text = ALIASES[v.toLowerCase()] || v;\n        var q = new GlideRecord('question_choice');\n        q.addQuery('text', text);\n        if (QUESTION) q.addQuery('question', QUESTION);\n        q.query();\n        if (q.getRowCount() == 1 && q.next()) { if (ids.indexOf(q.getUniqueValue()) < 0) ids.push(q.getUniqueValue()); return; }\n        log.warn('Sites: ' + (q.getRowCount() ? 'more than one choice \"' + text + '\" (set QUESTION)' : 'no choice for \"' + v + '\"') +\n            ' on ' + source.getValue('u_name'));\n    });\n    return ids.join(',');\n})(source);\n",
 "itreq": "// \"Import Asana HR Project Portfolio Transform Map\": field map -> u_it_required (IT Required)\n// Use source script = true, Choice action = ignore. Replace the WHOLE script of that field map with this file.\n// Asana \"I&T Integrations Needed\" (column u_i_t_integrations_needed) -> the IT Required choice with the same label.\n// DEV choices: No Integrations | Yes - New Integrations | Yes - Modify Existing Integrations\n// (\"No Integrations, but IT is engaged to support\" -> No Integrations; \"TBD\" -> blank).\n// Choices are stored on dmn_demand.u_it_required: no_integrations, yes_new_integrations, yes_modify_integrations.\n// v2: finds where the field's choices are really stored (the dictionary can point the choices to another table /\n// field), instead of assuming pm_project.u_it_required - v1 found nothing in DEV.\nanswer = (function transformEntry(source) {\n    var raw = (source.getValue('u_i_t_integrations_needed') || '').trim();\n    if (!raw || raw == 'undefined' || /^tbd$/i.test(raw)) return '';\n    var label = (/^no integrations/i.test(raw) ? 'No Integrations' : raw).toLowerCase();\n    var tables = ['pm_project', 'dmn_demand', 'planned_task', 'task'], element = 'u_it_required';   // choices live on dmn_demand (seen in TEST)\n    var d = new GlideRecord('sys_dictionary');\n    d.addQuery('name', 'IN', tables.join(','));\n    d.addQuery('element', element);\n    d.query();\n    if (d.next()) {                                           // choices taken from another table / field?\n        if (d.getValue('choice_table')) tables = [d.getValue('choice_table')].concat(tables);\n        if (d.getValue('choice_field')) element = d.getValue('choice_field');\n    }\n    var c = new GlideRecord('sys_choice');\n    c.addQuery('name', 'IN', tables.join(','));\n    c.addQuery('element', element);\n    c.addQuery('inactive', '!=', true);\n    c.query();\n    var seen = [];\n    while (c.next()) {\n        seen.push(c.getValue('name') + '.' + c.getValue('label') + '=' + c.getValue('value'));\n        if ((c.getValue('label') || '').toLowerCase() == label || (c.getValue('value') || '').toLowerCase() == label)\n            return c.getValue('value');\n    }\n    log.warn('IT Required: no choice for Asana \"' + raw + '\" on ' + source.getValue('u_name') + ' | choices found (' +\n        tables.join(',') + '.' + element + '): ' + (seen.join('; ') || 'NONE'));\n    return '';\n})(source);\n"
};
var WANT = [
    { source: 'u_correlation_id', target: 'correlation_id', coalesce: true },
    { source: 'u_name', target: 'short_description' },
    { target: 'project_manager', script: S.user },
    { target: 'assigned_to', script: S.user },
    { target: 'u_business_owner', script: S.owner },
    { target: 'primary_portfolio', script: S.portfolio },
    { target: 'u_functional_area', script: S.fa },
    { target: 'description', script: S.desc },
    { target: 'start_date', script: S.start, fmt: 'yyyy-MM-dd HH:mm:ss' },
    { target: 'end_date', script: S.end, fmt: 'yyyy-MM-dd HH:mm:ss' },
    { target: 'state', script: S.state },
    { target: 'on_hold', script: S.onhold },
    { target: 'u_sites', script: S.sites },
    { target: 'u_it_required', script: S.itreq }
];
var REMOVE = ['primary_program'];
var m = new GlideRecord('sys_transform_map');
if (!m.get('name', MAP_NAME)) gs.print('STOP: no transform map named ' + MAP_NAME);
else {
    gs.print((DRY_RUN ? 'DRY RUN - ' : '') + 'setting up ' + MAP_NAME);
    var have = {}, e = new GlideRecord('sys_transform_entry');
    e.addQuery('map', m.getUniqueValue()); e.query();
    while (e.next()) {
        var tf = e.getValue('target_field');
        var wanted = WANT.some(function (w) { return w.target == tf; });
        if (REMOVE.indexOf(tf) > -1 || (wanted && have[tf])) { gs.print('delete field map -> ' + tf); if (!DRY_RUN) e.deleteRecord(); continue; }
        if (wanted) have[tf] = e.getUniqueValue();
        else gs.print('left as is: ' + (e.getValue('source_field') || '[script]') + ' -> ' + tf +
            (e.getValue('use_source_script') == '1' && (e.getValue('source_script') || '').indexOf("return '';") < 0 ? '   (!! script has no return \'\' - may write "undefined")' : ''));
    }
    WANT.forEach(function (w) {
        var r = new GlideRecord('sys_transform_entry');
        var exists = have[w.target] && r.get(have[w.target]);
        if (!exists) { r.initialize(); r.setValue('map', m.getUniqueValue()); r.setValue('source_table', m.getValue('source_table')); r.setValue('target_table', m.getValue('target_table')); }
        r.setValue('target_field', w.target);
        r.setValue('source_field', w.source || '');
        r.setValue('use_source_script', w.script ? true : false);
        r.setValue('source_script', w.script || '');
        r.setValue('coalesce', w.coalesce ? true : false);
        r.setValue('choice_action', 'ignore');
        if (w.fmt) r.setValue('date_format', w.fmt);
        gs.print((exists ? 'update' : 'create') + ' field map ' + (w.source || '[script]') + ' -> ' + w.target);
        if (!DRY_RUN) { if (exists) r.update(); else r.insert(); }
    });
    gs.print(DRY_RUN ? 'DRY RUN done - set DRY_RUN = false to apply' : 'Done.');
}
